from collections import deque

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def zigzag_level_order(self, root):
        """Return zigzag level-order traversal of binary tree."""
        if not root:
            return []

        result = []
        queue = deque([root])
        left_to_right = True

        while queue:
            level_size = len(queue)
            nodes_for_level = deque()

            for _ in range(level_size):
                node = queue.popleft()

                if left_to_right:
                    nodes_for_level.append(node.val)
                else:
                    nodes_for_level.appendleft(node.val)

                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)

            result.append(list(nodes_for_level))
            left_to_right = not left_to_right

        return result
